 * (`paygent-relay-messages` and `paygent-x402`). This is the relay one, the
 * only one that crosses a binding; shadowing both would collide in Swift's
 * single flat module.
 */
public struct Eip3009Authorization {
    public var intentId: String
    public var from: String
    public var to: String
    public var value: String
    public var validAfter: String
    public var validBefore: String
    public var nonce: String
    public var encodedSignature: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(intentId: String, from: String, to: String, value: String, validAfter: String, validBefore: String, nonce: String, encodedSignature: String) {
        self.intentId = intentId
        self.from = from
        self.to = to
        self.value = value
        self.validAfter = validAfter
        self.validBefore = validBefore
        self.nonce = nonce
        self.encodedSignature = encodedSignature
    }
}

