    public static func ==(lhs: Eip3009Authorization, rhs: Eip3009Authorization) -> Bool {
        if lhs.intentId != rhs.intentId {
            return false
        }
        if lhs.from != rhs.from {
            return false
        }
        if lhs.to != rhs.to {
            return false
        }
        if lhs.value != rhs.value {
            return false
        }
        if lhs.validAfter != rhs.validAfter {
            return false
        }
        if lhs.validBefore != rhs.validBefore {
            return false
        }
        if lhs.nonce != rhs.nonce {
            return false
        }
        if lhs.encodedSignature != rhs.encodedSignature {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(intentId)
        hasher.combine(from)
        hasher.combine(to)
        hasher.combine(value)
        hasher.combine(validAfter)
        hasher.combine(validBefore)
        hasher.combine(nonce)
        hasher.combine(encodedSignature)
    }
}



